mapper.select:
SELECT om.order_id AS orderId, om.order_no AS orderNo, om.out_order_no AS outOrderNo, ca.channel_name AS channelName, COALESCE(rc.display_name, rc.name) AS roomCategoryName, r.room_name AS roomName, om.guest_name AS guestName, om.guest_mobile AS guestMobile, om.status AS orderStatus, om.start_at AS startAt, om.end_at AS endAt, om.created_at AS createdAt, COALESCE(om.settlement_amount_cent, 0) AS settlementAmountCent, COALESCE(NULLIF(om.distribution_commission_cent, 0), om.settlement_amount_cent, om.total_pay_price_cent, om.total_price_cent, 0) AS replaceAmountCent, COALESCE(om.remark, '') AS remark FROM order_main om LEFT JOIN channel_account ca ON ca.account_id = om.channel_id AND ca.camp_id = om.camp_id LEFT JOIN room_category rc ON rc.room_category_id = om.room_category_id AND rc.camp_id = om.camp_id LEFT JOIN room r ON r.room_id = om.room_id AND r.camp_id = om.camp_id WHERE om.camp_id = #{campId} AND om.is_deleted = 0 AND om.source_type = 'distribution_replace'
AND om.created_at >= #{rangeStart}
AND om.created_at < #{rangeEndExclusive}
ORDER BY om.created_at ASC, om.order_id ASC
